/**
 * Continuous effects generated by a resolving spell or ability (CR 611.2): "gets +N/+N", "has base
 * power and toughness 1/1", "loses all abilities", "becomes a Frog", "becomes blue" and "gains
 * flying", each until end of turn. One effect node makes one `ContinuousEffect` in the game state.
 *
 * - CR 611.2a: it lasts as long as the spell or ability says, here until end of turn. A node with
 *   no stated duration would last until the end of the game (`permanent`); no supported card has
 *   one (SUPPORTED_FEATURES.durationKinds), but the interpreter runs it.
 * - CR 611.2c: it modifies characteristics, so the objects it affects are fixed when it begins.
 *   An object that leaves the battlefield and returns is a new object (CR 400.7) and is not in it;
 *   a creature that enters later is not either.
 * - CR 613.7b: it receives a timestamp when it is created.
 * - CR 613.1, 613.4: `derive` applies it in the layer its change belongs to (`derive-layers.ts`).
 * - CR 514.2: the cleanup step removes the ones that last until end of turn.
 */
import type { Ability, Effect, PtAmount } from '../ast/types';
import type { ObjectId, SeatId } from '../ids';
import type { GameEvent } from '../state/events';
import { allocateTimestamp } from '../state/ops';
import type {
  ChosenTarget,
  ContinuousChange,
  ContinuousEffect,
  GameObject,
  GameState,
} from '../state/types';
import { dropEffects, endOf } from './control-effects';
import { copiableValues } from './copiable';
import { derive } from './derive';
import { ptAmountOf } from './effect-support';
import { resolveObjects, type SelectContext } from './select';
import { done, type StepOutcome } from './step-outcome';

/** The effect nodes that make a continuous effect. */
export type ContinuousNode = Extract<
  Effect,
  {
    kind:
      | 'modifyPt'
      | 'setPt'
      | 'loseAllAbilities'
      | 'setTypes'
      | 'setColors'
      | 'grantKeyword'
      | 'grantAbility'
      | 'restrict';
  }
>;

/** What the node changes, in the form the game state keeps it. */
function changeOf(
  state: GameState,
  node: ContinuousNode,
  ctx: SelectContext,
  targets: readonly ChosenTarget[],
  /** The object an `affected` amount reads (D-145): its power and toughness as the effect resolves. */
  own?: GameObject,
): ContinuousChange {
  switch (node.kind) {
    case 'modifyPt':
    case 'setPt': {
      // CR 611.2c, 608.2h: what the amounts come to is fixed as the effect resolves; X is the X of the
      // spell or ability that resolves (D-115).
      const now = own === undefined ? undefined : derive(state, own);
      return {
        kind: node.kind,
        power: ptAmountOf(state, node.power, ctx, targets, now),
        toughness: ptAmountOf(state, node.toughness, ctx, targets, now),
      };
    }
    case 'loseAllAbilities':
      return { kind: 'loseAllAbilities' };
    case 'setTypes':
      return {
        kind: 'setTypes',
        ...(node.types === undefined ? {} : { types: node.types }),
        ...(node.subtypes === undefined ? {} : { subtypes: node.subtypes }),
        ...(node.additive === true ? { additive: true as const } : {}),
      };
    case 'setColors':
      return { kind: 'setColors', colors: node.colors };
    case 'grantKeyword':
      return { kind: 'grantKeyword', keyword: node.keyword };
    case 'grantAbility':
      // D-230 (Backup): one change for each ability; `runContinuous` makes a continuous effect of each.
      return { kind: 'grantAbility', ability: node.abilities[0] as Ability };
    case 'restrict':
      return { kind: 'restrict', restriction: node.restriction };
    default: {
      const unreachable: never = node;
      return unreachable;
    }
  }
}

/** Runs a continuous-effect node: records an effect for the permanents the selector names right now. */
export function runContinuous(
  state: GameState,
  node: ContinuousNode,
  ctx: SelectContext,
  targets: readonly ChosenTarget[],
): StepOutcome {
  // CR 611.2c: the set is fixed now. A target that is no longer a permanent is skipped (CR 608.2b).
  const affected = resolveObjects(state, node.objects, ctx, targets).filter(
    (id) => state.objects[id]?.zone === 'battlefield',
  );
  if (affected.length === 0) return done(state);
  // CR 611.2b (D-196): "for as long as you control this" does nothing when the duration is over before the effect would begin.
  const until =
    node.duration === 'forAsLongAsYouControlThis' || node.duration === 'forAsLongAsThisRemains'
      ? endOf(state, node.duration, ctx)
      : node.duration === 'untilEndOfTurn'
        ? ('endOfTurn' as const)
        : ('permanent' as const);
  if (until === null) return done(state);
  // CR 613.1f, 702.165a (D-230): Backup's grant: one effect for each ability, in the order they are written (one timestamp each).
  if (node.kind === 'grantAbility') {
    let next = state;
    const made: ContinuousEffect[] = [];
    for (const ability of node.abilities) {
      const [timestamp, stamped] = allocateTimestamp(next);
      next = stamped;
      made.push({
        id: `ce${timestamp}`,
        timestamp,
        objects: affected,
        until,
        change: { kind: 'grantAbility', ability },
      });
    }
    return done({ ...next, continuousEffects: [...next.continuousEffects, ...made] });
  }
  // CR 701.10b (D-145): "double the power and toughness of each creature": each creature gets +X/+Y with its own power and toughness,
  // all read before any of the effects exists. One continuous effect for each creature.
  if (node.kind === 'modifyPt' && (readsAffected(node.power) || readsAffected(node.toughness))) {
    let next = state;
    const made: ContinuousEffect[] = [];
    for (const id of affected) {
      const obj = state.objects[id];
      if (obj === undefined) continue;
      const [timestamp, stamped] = allocateTimestamp(next);
      next = stamped;
      made.push({
        id: `ce${timestamp}`,
        timestamp,
        objects: [id],
        until,
        change: changeOf(state, node, ctx, targets, obj),
      });
    }
    return done({ ...next, continuousEffects: [...next.continuousEffects, ...made] });
  }
  const [timestamp, stamped] = allocateTimestamp(state);
  const created: ContinuousEffect = {
    id: `ce${timestamp}`,
    timestamp,
    objects: affected,
    until,
    change: changeOf(state, node, ctx, targets),
  };
  // D-217 (CR 613.4b): "becomes a 4/4 artifact creature": the base power and toughness of the same permanents, a second effect of layer 7b.
  if (node.kind === 'setTypes' && node.basePt !== undefined) {
    const [ptStamp, both] = allocateTimestamp(stamped);
    const pt: ContinuousEffect = {
      id: `ce${ptStamp}`,
      timestamp: ptStamp,
      objects: affected,
      until,
      change: { kind: 'setPt', power: node.basePt.power, toughness: node.basePt.toughness },
    };
    return done({ ...both, continuousEffects: [...both.continuousEffects, created, pt] });
  }
  return done({ ...stamped, continuousEffects: [...stamped.continuousEffects, created] });
}

const readsAffected = (a: PtAmount): boolean => typeof a !== 'number' && a.kind === 'affected';

/**
 * "Target creature becomes a copy of target creature" (CR 707.2, 613.2a): a layer 1 `copy` effect
 * for the permanents `objects` names, carrying the copiable values of `of` as they are right now
 * (CR 707.2b). The original may have left the battlefield since it was chosen: its last-known
 * information is copied (CR 608.2h). Nothing happens when it cannot be found, or for a target that
 * is no longer a permanent (CR 608.2b).
 */
export function runBecomeCopy(
  state: GameState,
  node: Extract<Effect, { kind: 'becomeCopy' }>,
  ctx: SelectContext,
  targets: readonly ChosenTarget[],
): StepOutcome {
  const sourceId = resolveObjects(state, node.of, ctx, targets)[0];
  const source =
    sourceId === undefined ? undefined : (state.objects[sourceId] ?? state.lki[sourceId]?.object);
  const affected = resolveObjects(state, node.objects, ctx, targets).filter(
    (id) => state.objects[id]?.zone === 'battlefield',
  );
  if (source === undefined || affected.length === 0) return done(state);
  return copyEffect(state, node, source, affected);
}

/**
 * The layer 1 `copy` effect that gives each of `affected` the copiable values of `source` as they are now (CR 707.2b), for the duration of `node` (D-232 also: a card in a
 * zone other than the battlefield is copied, `becomeCopyOfCard`).
 */
export function copyEffect(
  state: GameState,
  node: Pick<Extract<Effect, { kind: 'becomeCopy' }>, 'duration' | 'keepName' | 'addTypes'>,
  source: GameObject,
  affected: readonly ObjectId[],
): StepOutcome {
  const until = node.duration === 'untilEndOfTurn' ? 'endOfTurn' : 'permanent';
  const original = copiableValues(state, source);
  // D-217 (CR 707.9b): "except it's an artifact in addition to its other types" changes the copiable values the copy effect gives.
  const added = (node.addTypes ?? []).filter((t) => !original.characteristics.types.includes(t));
  const copied =
    added.length === 0
      ? original
      : {
          ...original,
          characteristics: {
            ...original.characteristics,
            types: [...original.characteristics.types, ...added],
          },
        };
  // D-212 (CR 707.9a): "except its name is ~": each permanent keeps the name it has, so there is one effect for each.
  const groups: readonly (readonly ObjectId[])[] =
    node.keepName === true ? affected.map((id) => [id]) : [affected];
  let next = state;
  const made: ContinuousEffect[] = [];
  for (const objects of groups) {
    const [timestamp, stamped] = allocateTimestamp(next);
    next = stamped;
    const own = node.keepName === true ? state.objects[objects[0] as ObjectId] : undefined;
    made.push({
      id: `ce${timestamp}`,
      timestamp,
      objects,
      until,
      change: {
        kind: 'copy',
        values:
          own === undefined
            ? copied
            : {
                ...copied,
                characteristics: {
                  ...copied.characteristics,
                  name: copiableValues(state, own).characteristics.name,
                },
              },
      },
    });
  }
  // D-212: a permanent that became a copy is something done, for "if you do".
  return {
    ...done({ ...next, continuousEffects: [...next.continuousEffects, ...made] }),
    performed: 1,
  };
}

/**
 * "Until your next turn, creatures your opponents control attack each combat if able and attack a player other than you if able" (CR 508.1d, 611.2a,
 * 611.2c, D-179): one continuous effect with no set of objects, read where attackers are declared for the creatures its filter matches then (a
 * requirement changes the rules, so it reaches creatures that arrive later). `until` is the end of this turn, or the start of the next turn of the
 * controller (the one that comes after this moment, not this turn even when it is theirs).
 */
export function runRequireAttack(
  state: GameState,
  node: Extract<Effect, { kind: 'requireAttack' }>,
  ctx: SelectContext,
): StepOutcome {
  const [timestamp, stamped] = allocateTimestamp(state);
  const taken = state.seats[ctx.controller]?.turnsTaken ?? 0;
  const created: ContinuousEffect = {
    id: `ce${timestamp}`,
    timestamp,
    objects: [],
    until:
      node.duration === 'untilEndOfTurn'
        ? 'endOfTurn'
        : { kind: 'turnStart', seat: ctx.controller, turnsTaken: taken + 1 },
    change: {
      kind: 'requireAttack',
      filter: node.creatures,
      controller: ctx.controller,
      ...(node.awayFromYou === true ? { awayFrom: ctx.controller } : {}),
    },
  };
  return done({ ...stamped, continuousEffects: [...stamped.continuousEffects, created] });
}

/**
 * "Until your next turn" (D-179, CR 500.1): the effects waiting for a turn of `seat` end as that turn begins, when it is the turn they were
 * waiting for (numbered as they say or later).
 */
export function expireTurnStartEffects(
  state: GameState,
  seat: SeatId,
): { state: GameState; events: GameEvent[] } {
  const taken = state.seats[seat]?.turnsTaken ?? 0;
  return dropEffects(
    state,
    (e) =>
      typeof e.until === 'object' &&
      e.until.kind === 'turnStart' &&
      e.until.seat === seat &&
      e.until.turnsTaken <= taken,
  );
}

/**
 * CR 514.2: "until end of turn" effects end, at the same moment damage is removed. So do those that last until the end of a turn of the
 * player whose turn this is ("until the end of your next turn", D-151). A permanent that goes back to its controller as a control effect ends
 * is reported (`controlChanged`, D-189).
 */
export function expireEndOfTurnEffects(state: GameState): {
  state: GameState;
  events: GameEvent[];
} {
  const active = state.turn.activeSeat;
  const taken = state.seats[active]?.turnsTaken ?? 0;
  return dropEffects(
    state,
    (e) =>
      e.until === 'endOfTurn' ||
      (typeof e.until === 'object' &&
        e.until.kind === 'turnEnd' &&
        e.until.seat === active &&
        e.until.turnsTaken <= taken),
  );
}

/**
 * "Until your next end step" (D-151, CR 611.2a, 500.1): an effect of that kind ends as the end step of the player whose turn it is begins,
 * when it was waiting for a turn of theirs numbered as this one or earlier.
 */
export function expireEndStepEffects(state: GameState): { state: GameState; events: GameEvent[] } {
  const active = state.turn.activeSeat;
  const taken = state.seats[active]?.turnsTaken ?? 0;
  return dropEffects(
    state,
    (e) =>
      typeof e.until === 'object' &&
      e.until.kind === 'endStep' &&
      e.until.seat === active &&
      e.until.turnsTaken <= taken,
  );
}
